def f4(A):
    A=np.array(A); H,W=A.shape; out=A.copy()
    for r in range(H):
        for c in range(W):
            v=int(A[r,c])
            rs=list(range(max(0,r-1),min(H,r+2))); cs2=list(range(max(0,c-1),min(W,c+2)))
            nb=[int(A[i2,c2]) for i2 in rs for c2 in cs2 if (i2,c2)!=(r,c)]
            same=sum(x==v for x in nb)
            cnt={}
            for x in nb: cnt[x]=cnt.get(x,0)+1
            mx=max(cnt.values()); cand=[x for x,k in cnt.items() if k==mx]
            nv=cand[0] if len(cand)==1 else 1
            # tie-break with larger overall count wins among ties; fallback to 1
            if len(cand)>1:
                tot={}; 
                for i2 in range(H):
                    for c2 in range(W):
                        tot[int(A[i2,c2])]=tot.get(int(A[i2,c2]),0)+1
                best=max(cand,key=lambda x:tot[x]); mv=tot[best]
                rest=sorted([x for x in cand if x!=best],key=lambda x:tot[x],reverse=True)
                if rest and len(rest)==1 and mv-rest[0]>0: pass
                else: nv=1
                # pick candidate with min total manhattan distance of nbr cells that color? Use nearest nbr tiebreak:
                # prefer neighbor having the majority color closest to cell center
                dsum={}
                for i2 in range(max(0,r-1),min(H,r+2)):
                    for c2 in range(max(0,c-1),min(W,c+2)):
                        if (i2,c2)!=(r,c):
                            dsum[int(A[i2,c2])]=dsum.get(int(A[i2,c2]),99)+abs(r-i2)+abs(c-c2)
                nv=min(cand,key=lambda x:(dsum.get(x,99),-tot[x]))
            out[r,c]=nv
    return out.tolist()
